workspace "Hospital Appointment System" "A minimal C4 model of a hospital appointment system." {

    model {
        patient = person "Patient" "A patient who books and manages hospital appointments."

        appointmentSystem = softwareSystem "Appointment System" "Allows patients to book and manage hospital appointments." {
            bookingWebApp = container "Booking Web App" "A web application that patients use to book appointments." "ASP.NET Core MVC"
            schedulingService = container "Scheduling Service" "Manages appointment scheduling and room availability." "Java"
        }

        patient -> bookingWebApp "Books and manages appointments" "HTTPS"
        bookingWebApp -> schedulingService "Creates and updates appointments" "gRPC"
    }

    views {
        systemContext appointmentSystem "SystemContext" "Shows the Patient and the Appointment System." {
            include *
            autoLayout
        }
    }
}

workspace "Hospital Appointment System" "A C4 model of a hospital appointment system." {

    model {
        patient = person "Patient" "A patient who books and manages hospital appointments."

        appointmentSystem = softwareSystem "Appointment System" "Allows patients to book and manage hospital appointments." {
            bookingWebApp = container "Booking Web App" "Web application that patients use to book appointments." "ASP.NET Core MVC"
            schedulingService = container "Scheduling Service" "Schedules appointments and manages doctor availability." "Java"

            bookingWebApp -> schedulingService "Requests appointment slots" "gRPC"
        }

        patient -> appointmentSystem "Books appointments" "HTTPS"
        patient -> bookingWebApp "Books appointments through" "HTTPS"
    }

    views {
        systemContext appointmentSystem "SystemContext" "Shows the Patient and the Appointment System." {
            include *
        }
    }
}

workspace "Hospital Appointment System" "A small C4 model of a hospital appointment system" {
    model {
        patient = person "Patient" "A patient who books and manages hospital appointments."
        appointmentSystem = softwareSystem "Appointment System" "Manages hospital appointments, from booking to scheduling." {
            bookingWebApp = container "Booking Web App" "A web application where patients book and view appointments." "React"
            schedulingService = container "Scheduling Service" "Assigns appointments to clinicians and rooms." "Java/Spring"
        }

        patient -> bookingWebApp "Books and views appointments through" "HTTPS/HTML"
        bookingWebApp -> schedulingService "Submits booking requests to" "REST/JSON"
    }

    views {
        systemContext appointmentSystem "AppointmentSystemContext" "System context view of the Appointment System." {
            include *
            autoLayout
        }
        container appointmentSystem "AppointmentSystemContainers" "Container view of the Appointment System." {
            include *
            autoLayout
        }
    }

    configuration {
        scope softwaresystem
    }
}

